}

query SuggestedRefundToStoreCredit($id: ID!, $refundLineItems: [RefundLineItemInput!], $refundMethodAllocation: RefundMethodAllocation!) {
  order(id: $id) {
    id
    suggestedRefund(refundLineItems: $refundLineItems, refundMethodAllocation: $refundMethodAllocation) {
      subtotalSet {
        presentmentMoney {
          amount
          currencyCode
        }
      }
      refundLineItems {
        lineItem {
          id
        }
        quantity
      }
      suggestedTransactions {
        parentTransaction {
          id
        }
        gateway
        formattedGateway
        amountSet {
          presentmentMoney {
            amount
            currencyCode
          }
        }
      }
      suggestedRefundMethods {
        __typename
        amount {
          presentmentMoney {
            amount
            currencyCode
          }
        }
      }
    }
  }
}

query SuggestedRefund($id: ID!, $refundLineItems: [RefundLineItemInput!]) {
  order(id: $id) {
    id
    suggestedRefund(refundLineItems: $refundLineItems) {
      subtotalSet {
        shopMoney {
          amount
          currencyCode
        }
        presentmentMoney {
          amount
          currencyCode
        }
      }
      refundLineItems {
        lineItem {
          id
        }
        quantity
      }
    }
  }
}

query {
  node(id: "gid://shopify/Order/148977776") {
    id
    ... on Order {
      name
    }
  }
}

query OrderMetafields($ownerId: ID!) {
  order(id: $ownerId) {
    metafields(first: 3) {
      edges {
        node {
          namespace
          key
          value
        }
      }
    }
  }
}

query FulfillmentsCount($orderId: ID!) {
  order(id: $orderId) {
    fulfillmentsCount {
      count
    }
  }
}

query TransactionsCountForOrder($orderId: ID!) {
  order(id: $orderId) {
    transactionsCount {
      count
    }
  }
}

query FulfillmentOrderList($orderId: ID!) {
  order(id: $orderId) {
    fulfillmentOrders(first: 250) {
      nodes {
        id
        createdAt
        updatedAt
        requestStatus
        status
        fulfillAt
        destination {
          id
          address1
          address2
          city
          company
          countryCode
          email
          firstName
          lastName
          phone
          province
          zip
        }
        lineItems(first: 250) {
          nodes {
            id
            totalQuantity
            inventoryItemId
            remainingQuantity
            variant {
              id
            }
          }
        }
        internationalDuties {
          incoterm
        }
        fulfillmentHolds {
          reason
          reasonNotes
        }
        fulfillBy
        deliveryMethod {
          id
          methodType
          minDeliveryDateTime
          maxDeliveryDateTime
          additionalInformation {
            instructions
            phone
          }
          serviceCode
          sourceReference
          presentedName
          brandedPromise {
            handle
            name
          }
        }
        assignedLocation {
          address1
          address2
          city
          countryCode
          location {
            id
          }
          name
          phone
          province
          zip
        }
        merchantRequests(first: 250) {
          nodes {
            message
            requestOptions
            kind
          }
        }
      }
    }
  }
}

query TransactionsForOrder($orderId: ID!) {
  order(id: $orderId) {
    transactions(first: 10) {
      accountNumber
      amountSet {
        presentmentMoney {
          amount
          currencyCode
        }
        shopMoney {
          amount
          currencyCode
        }
      }
      authorizationCode
      authorizationExpiresAt
      createdAt
      errorCode
      fees {
        amount {
          amount
          currencyCode
        }
      }
      formattedGateway
      gateway
      id
      kind
      manuallyCapturable
      maximumRefundableV2 {
        amount
        currencyCode
      }
      multiCapturable
      order {
        id
      }
      parentTransaction {
        id
      }
      paymentDetails {
        ... on CardPaymentDetails {
          paymentMethodName
        }
        ... on ShopPayInstallmentsPaymentDetails {
          paymentMethodName
        }
      }
      paymentIcon {
        url
      }
      paymentId
      processedAt
      receiptJson
      settlementCurrency
      shopifyPaymentsSet {
        refundSet {
          acquirerReferenceNumber
        }
      }
      status
      test
      totalUnsettledSet {
        presentmentMoney {
          amount
          currencyCode
        }
        shopMoney {
          amount
          currencyCode
        }
      }
      user {
        id
      }
    }
  }
}

query OrderMetafield($namespace: String!, $key: String!, $ownerId: ID!) {
  order(id: $ownerId) {
    purchaseOrder: metafield(namespace: $namespace, key: $key) {
      value
    }
  }
}

